# Search for digitized Collins Spanish-English dictionaries from 1990s
print("=== Searching for digitized Collins Spanish-English dictionaries from 1990s ===")
queries = [
    "Collins Spanish-English dictionary 1990s digitized archive",
    "Collins Spanish English dictionary 1990s digital version",
    "Collins dictionary archive 1990s",
    "Collins Spanish-English dictionary online 1990s",
    "Collins dictionary digitized historical versions"
]

results = []
for query in queries:
    try:
        response = requests.get(f"https://api.duckduckgo.com/?q={query}&format=json")
        if response.status_code == 200:
            data = response.json()
            if 'Results' in data:
                for result in data['Results']:
                    results.append({
                        'title': result.get('Title', ''),
                        'url': result.get('FirstURL', ''),
                        'snippet': result.get('Snippet', '')
                    })
    except:
        pass

# Remove duplicates
unique_results = []
seen_urls = set()
for result in results:
    if result['url'] not in seen_urls:
        unique_results.append(result)
        seen_urls.add(result['url'])

print(f"Found {len(unique_results)} results for digitized dictionaries:")
for result in unique_results[:10]:
    print(f"- {result['title']}: {result['url']}")
    print(f"  {result['snippet']}")
    print()

